test('vatSummary with complex discounts and multiple VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier, 5% discount
    issueDate: '2025-10-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 }, // €1200, 5% discount €60, net €1140, VAT 21%: €239.40
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 }, // €850, 10% discount €85, net €765, VAT 21%: €160.65
      { sku: 'BOOK-DESIGN', qty: 5 }, // €124.50 * 5 = €622.50, 5% tier discount €31.13, net €591.37, VAT 9%: €53.22
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 190500); // 114000 + 76500
  assert.equal(result[0].vat, 40005); // 23940 + 16065
  assert.equal(result[1].rate, 9);
  assert.equal(result[1].base, 11828); // 2490 * 5 - (2490 * 5 * 5 / 100) rounded
  assert.equal(result[1].vat, 1065); // 11828 * 9 / 100 rounded
});

