test('lateFee calculates on partially paid invoice', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €514.25
    terms: 'NET14', // due 2025-10-29
  }).value;
  let issued = issueInvoice(invoice, []).value;
  issued = recordPayment(issued, { amount: 25000, date: '2025-10-25' }).value;
  assert.equal(issued.status, 'partially_paid');

  // 7 days overdue, balance due = 51425 - 25000 = 26425
  // fee = 26425 * 7 * 0.04 / 100 = 73.79 → 74 cents
  const fee = lateFee(issued, '2025-11-05');
  assert.equal(fee, 74);
});

test('lateFee with large balance due', () => {
  const invoice = createInvoice({
