  // 30 days overdue: 51425 * 30 * 0.04 / 100 = 617.10 → 617 cents
  const fee = lateFee(issued, '2025-11-28');
  assert.equal(fee, 617);
});

test('lateFee with NET30 terms', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }], // €850, bulk 2.5% €21.25, net €828.75, VAT €174.04, total €1002.79
    terms: 'NET30', // due 2025-11-14
  }).value;
  const issued = issueInvoice(invoice, []).value;

  // 5 days overdue: 100279 * 5 * 0.04 / 100 = 200.558 → 201 cents
  const fee = lateFee(issued, '2025-11-19');
  assert.equal(fee, 201);
});

test('lateFee with EOM terms', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €514.25
    terms: 'EOM', // due 2025-10-31
  }).value;
  const issued = issueInvoice(invoice, []).value;

  // 5 days overdue: 51425 * 5 * 0.04 / 100 = 102.85 → 103 cents
  const fee = lateFee(issued, '2025-11-05');
  assert.equal(fee, 103);
});

test('lateFee with small balance due rounds correctly', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €514.25
    terms: 'NET14', // due 2025-10-29
  }).value;
  let issued = issueInvoice(invoice, []).value;
  // Pay almost everything, leaving small balance
  issued = recordPayment(issued, { amount: 51400, date: '2025-10-25' }).value;

  // 7 days overdue, balance due = 25
  // fee = 25 * 7 * 0.04 / 100 = 0.07 → 0 cents (rounds to 0)
  const fee = lateFee(issued, '2025-11-05');
  assert.equal(fee, 0);
});

test('lateFee accumulates with multiple days', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }], // €85, VAT €17.85, total €102.85
    terms: 'NET14', // due 2025-10-29
  }).value;
  const issued = issueInvoice(invoice, []).value;

  // 1 day: 10285 * 1 * 0.04 / 100 = 4.114 → 4 cents
  const fee1 = lateFee(issued, '2025-10-30');
  assert.equal(fee1, 4);

  // 2 days: 10285 * 2 * 0.04 / 100 = 8.228 → 8 cents
  const fee2 = lateFee(issued, '2025-10-31');
  assert.equal(fee2, 8);

  // 3 days: 10285 * 3 * 0.04 / 100 = 12.342 → 12 cents
  const fee3 = lateFee(issued, '2025-11-01');
  assert.equal(fee3, 12);
});

