  issued = recordPayment(issued, { amount: 51400, date: '2025-10-25' }).value;

  // 7 days overdue, balance due = 25
  // fee = 25 * 7 * 0.04 / 100 = 0.07 → 0 cents (rounds to 0)
  const fee = lateFee(issued, '2025-11-05');
  assert.equal(fee, 0);
});

test('lateFee accumulates with multiple days', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }], // €85, VAT €17.85, total €102.85
    terms: 'NET14', // due 2025-10-29
  }).value;
  const issued = issueInvoice(invoice, []).value;

  // 1 day: 10285 * 1 * 0.04 / 100 = 4.114 → 4 cents
  const fee1 = lateFee(issued, '2025-10-30');
  assert.equal(fee1, 4);

  // 2 days: 10285 * 2 * 0.04 / 100 = 8.228 → 8 cents
  const fee2 = lateFee(issued, '2025-10-31');
  assert.equal(fee2, 8);

  // 3 days: 10285 * 3 * 0.04 / 100 = 12.342 → 12 cents
  const fee3 = lateFee(issued, '2025-11-01');
  assert.equal(fee3, 12);
});

test('dashboard returns empty counts for no invoices', () => {
  const result = dashboard([], '2025-10-15');
  assert.deepEqual(result.counts, { draft: 0, issued: 0, partially_paid: 0, paid: 0 });
  assert.equal(result.outstanding, 0);
  assert.deepEqual(result.overdue, { count: 0, amount: 0 });
  assert.deepEqual(result.topCustomers, []);
});

test('dashboard counts invoices by status', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(inv2, []).value;

  let inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  let partially = issueInvoice(inv3, ['INV-2025-0001']).value;
  partially = recordPayment(partially, { amount: 5000, date: '2025-10-20' }).value;

  let inv4 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  let paid = issueInvoice(inv4, ['INV-2025-0001', 'INV-2025-0002']).value;
  paid = recordPayment(paid, { amount: 10285, date: '2025-10-20' }).value;

  const result = dashboard([draft, issued, partially, paid], '2025-10-31');

  assert.equal(result.counts.draft, 1);
  assert.equal(result.counts.issued, 1);
  assert.equal(result.counts.partially_paid, 1);
  assert.equal(result.counts.paid, 1);
});

test('dashboard calculates outstanding (issued + partially_paid)', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }], // 10285 cents
  }).value;
  const issued = issueInvoice(inv1, []).value;

  let inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }], // 10285 cents
  }).value;
  let partially = issueInvoice(inv2, ['INV-2025-0001']).value;
  partially = recordPayment(partially, { amount: 5000, date: '2025-10-20' }).value;

  let paid = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  paid = issueInvoice(paid, ['INV-2025-0001', 'INV-2025-0002']).value;
  paid = recordPayment(paid, { amount: 10285, date: '2025-10-20' }).value;

  const result = dashboard([issued, partially, paid], '2025-10-31');

  // Issued: 10285, Partially: 5285 (10285 - 5000), Paid: 0
  assert.equal(result.outstanding, 10285 + 5285);
});

test('dashboard includes overdue summary', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
