  const result = dashboard([issued1, issued2], '2025-10-25');

  // Only issued1 is overdue (due 2025-10-15, as of 2025-10-25)
  assert.equal(result.overdue.count, 1);
  assert.equal(result.overdue.amount, 51425);
});

test('dashboard identifies top customers by outstanding amount', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }], // 10285 cents
  }).value;
