test('dashboard identifies top customers by outstanding amount', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }], // 10285 cents
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // 51425 cents
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 2 }], // 20570 cents
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2025-0001', 'INV-2025-0002']).value;

  const inv4 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-04',
    lines: [{ sku: 'DES-HOUR', qty: 3 }], // 30855 cents
  }).value;
  const issued4 = issueInvoice(inv4, ['INV-2025-0001', 'INV-2025-0002', 'INV-2025-0003']).value;

  const result = dashboard([issued1, issued2, issued3, issued4], '2025-10-31');

  // C-001: 10285 + 30855 = 41140
  // C-002: 51425
  // C-003: 20570
  // Top 3: C-002 (51425), C-001 (41140), C-003 (20570)
  assert.equal(result.topCustomers.length, 3);
  assert.equal(result.topCustomers[0].customerId, 'C-002');
  assert.equal(result.topCustomers[0].due, 51425);
  assert.equal(result.topCustomers[1].customerId, 'C-001');
  assert.equal(result.topCustomers[1].due, 41140);
  assert.equal(result.topCustomers[2].customerId, 'C-003');
  assert.equal(result.topCustomers[2].due, 20570);
});

